def enable_tenant_rls(apps, schema_editor):
    connection = schema_editor.connection
    if connection.vendor != 'postgresql':
        raise RuntimeError('Tenant RLS requires PostgreSQL.')
    quote_name = schema_editor.quote_name
    with connection.cursor() as cursor:
        for table_name in TENANT_TABLES:
            table = quote_name(table_name)
            policy = quote_name(f'tenant_scope_{hashlib.sha256(table_name.encode()).hexdigest()[:10]}')
            tenant_scope = f'{quote_name("tenant_id")}::text = NULLIF(current_setting(\'app.tenant_id\', true), \'\')'
            cursor.execute(f'ALTER TABLE {table} ENABLE ROW LEVEL SECURITY')
            cursor.execute(f'ALTER TABLE {table} FORCE ROW LEVEL SECURITY')
            cursor.execute(f'CREATE POLICY {policy} ON {table} USING ({tenant_scope}) WITH CHECK ({tenant_scope})')


def disable_tenant_rls(apps, schema_editor):
    connection = schema_editor.connection
    if connection.vendor != 'postgresql':
        return
    quote_name = schema_editor.quote_name
    with connection.cursor() as cursor:
        for table_name in TENANT_TABLES:
            table = quote_name(table_name)
            policy = quote_name(f'tenant_scope_{hashlib.sha256(table_name.encode()).hexdigest()[:10]}')
            cursor.execute(f'DROP POLICY IF EXISTS {policy} ON {table}')
            cursor.execute(f'ALTER TABLE {table} NO FORCE ROW LEVEL SECURITY')
            cursor.execute(f'ALTER TABLE {table} DISABLE ROW LEVEL SECURITY')


